import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import {jest} from '@jest/globals';

describe('ToolRegistry Input Validation (Acceptance)', () => {
  afterEach(() => {
    setLogger(undefined); // Restore default logger
  });

  it('rejects missing required fields and does not call the executor', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#validation-contract
    const registry = new ToolRegistry();
    let called = false;
    registry.register(
      {
        name: 'test-tool',
        description: 'a test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        called = true;
        return 'ok';
      }
    );

    const response = await registry.execute('test-tool', {});

    expect(response.result).toContain('location');
    expect(response.result).toContain('required');
    expect(called).toBe(false);
  });

  it('passes through extra properties unchanged', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#validation-contract
    const registry = new ToolRegistry();
    let receivedInput: any;
    registry.register(
      {
        name: 'test-tool',
        description: 'a test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        receivedInput = input;
        return 'ok';
      }
    );

    const input = {location: 'London', extra: 'property'};
    await registry.execute('test-tool', input);

    expect(receivedInput).toEqual(input);
  });

  it('rejects wrong-typed fields and redacts values in result and logs', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#validation-contract
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test-tool',
        description: 'a test tool',
        inputSchema: {
          type: 'object',
          properties: {count: {type: 'number'}},
        },
      },
      async () => 'ok'
    );

    const secretValue = 'VERY_SECRET_VALUE';
    const logs: any[] = [];
    setLogger({
      debug: () => {},
      info: (cat, msg, fields) => logs.push({msg, fields}),
      warn: (cat, msg, fields) => logs.push({msg, fields}),
      error: (cat, msg, fields) => logs.push({msg, fields}),
    });

    const response = await registry.execute('test-tool', {count: secretValue} as any);

    // Assert result redaction
    expect(response.result).toContain('count');
    expect(response.result).toContain('number');
    expect(response.result).not.toContain(secretValue);

    // Assert log redaction
    const allLogText = JSON.stringify(logs);
    expect(allLogText).not.toContain(secretValue);
  });

  it('throws during registration for broken schemas', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#performance-and-reliability
    const registry = new ToolRegistry();
    const brokenSchema = {type: 'invalid-type'} as any;

    expect(() =>
      registry.register(
        {
          name: 'broken-tool',
          description: 'broken',
          inputSchema: brokenSchema,
        },
        async () => 'ok'
      )
    ).toThrow(/broken-tool/);
  });

  it('compiles static tool schema once', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#performance-and-reliability
    const registry = new ToolRegistry();
    let accessCount = 0;
    const schema = {
      type: 'object',
      get properties() {
        accessCount++;
        return {location: {type: 'string'}};
      },
    };

    registry.register(
      {
        name: 'static-tool',
        description: 'd',
        inputSchema: schema as any,
      },
      async () => 'ok'
    );

    const initialAccessCount = accessCount;
    expect(initialAccessCount).toBeGreaterThan(0); // Should have compiled at register time

    await registry.execute('static-tool', {location: 'London'});
    await registry.execute('static-tool', {location: 'Paris'});

    expect(accessCount).toBe(initialAccessCount); // Should not have re-accessed 'properties' during execution
  });

  it('validates against the current schema for function-valued definitions', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#performance-and-reliability
    const registry = new ToolRegistry();
    let schema: any = {type: 'object', properties: {a: {type: 'string'}}};

    registry.register(
      () => ({name: 'dynamic', description: 'd', inputSchema: schema}),
      async () => 'ok'
    );

    // First call with first schema
    const res1 = await registry.execute('dynamic', {a: 'hi'});
    expect(res1.result).toBe('ok');

    // Change schema
    schema = {type: 'object', properties: {a: {type: 'number'}}};
    const res2 = await registry.execute('dynamic', {a: 'hi'});
    expect(res2.result).not.toBe('ok');
    expect(res2.result).toContain('number');
  });

  it('throws Unknown tool for unregistered names', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#validation-contract
    const registry = new ToolRegistry();
    await expect(registry.execute('ghost', {})).rejects.toThrow('Unknown tool: ghost');
  });
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const capturingScriptedProvider = (rounds: MessageChunk[][]): {provider: AIProvider; history: any[]} => {
  let round = 0;
  const history: any[] = [];
  return {
    history,
    provider: {
      async *sendMessage(params): AsyncGenerator<MessageChunk> {
        history.push(params.messages);
        for (const chunk of rounds[round++] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    },
  };
};

describe('ChatOrchestrator Tool Input Validation (Acceptance)', () => {
  it('allows model to recover from a rejected tool call', async () => {
    // specs/hal-engine-tool-input-validation/spec.md#orchestration
    const registry = new ToolRegistry();
    let executorCalledCount = 0;
    registry.register(
      {
        name: 'test-tool',
        description: 'd',
        inputSchema: {type: 'object', properties: {a: {type: 'number'}}, required: ['a']},
      },
      async () => {
        executorCalledCount++;
        return 'success';
      }
    );

    const TOOL_CALL_INVALID: MessageChunk = {
      type: 'tool_use',
      toolCall: {id: 'c1', name: 'test-tool', input: {a: 'not-a-number'}},
    };
    const TOOL_CALL_VALID: MessageChunk = {
      type: 'tool_use',
      toolCall: {id: 'c2', name: 'test-tool', input: {a: 42}},
    };
    const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
    const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

    const {provider, history} = capturingScriptedProvider([
      [TOOL_CALL_INVALID, STOP_FOR_TOOL],
      [TOOL_CALL_VALID, STOP_FOR_TOOL],
      [{type: 'text', text: 'got it'}, STOP_DONE],
    ]);

    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'i'}), registry);
    const session = createSession('do something');

    const result = await orchestrator.processMessage(session);

    expect(result).toBe('got it');
    expect(executorCalledCount).toBe(1); // Should only be called once (the valid call)

    // Check round 1 history (after round 0 produced TOOL_CALL_INVALID)
    // history[0] is round 0 (input: user message)
    // history[1] is round 1 (input: user message + assistant tool call + user tool result)
    expect(history).toHaveLength(3);

    const round1Messages = history[1];
    const lastMessage = round1Messages[round1Messages.length - 1];
    expect(lastMessage.role).toBe('user');
    expect(Array.isArray(lastMessage.content)).toBe(true);
    expect(lastMessage.content[0].type).toBe('tool_result');
    expect(lastMessage.content[0].content).toContain('number'); // The rejection message
  });
});

